    }
    dts_Master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ENG_TRANSL_OBJ_EMAIL_LIST";
    dts_Master.Reset();
    dts_Master.insertRow();
    dts_Receiver.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ENG_TRANSL_OBJ_EMAIL_LIST";
    dts_Receiver.Reset();

    // 파일: 가우스헤더 셋팅
