    $c.stf.setObjectValue(txa_content, "첨부파일 영문번역 부탁드립니다.");
    $c.stf.setObjectValue(txb_EMP_NO, js_emp_no);
    dts_Receiver.insertRow();
    dts_Receiver.setCellData(1, "CHECK", "T");
    dts_Receiver.setCellData(1, "NM", "이포넷 담당자");
    dts_Receiver.setCellData(1, "EMAIL", /*ORG SRC: dts_Receiver.setNameString(1, "EMAIL", dts_Receiver.NameString(1, "EMAIL") = );*/ X = X);
    dts_Receiver.insertRow();
    dts_Receiver.setCellData(2, "CHECK", "");
    dts_Receiver.setCellData(2, "NM", "");
    dts_Receiver.setCellData(2, "EMAIL", "");
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_mailList);
    var url = "/DsclSearchAll.do?method=listSendEmail";
    url += "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(txb_LdMktTpCd);
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_emailList.DataID = encodeURI(url);
    dts_emailList.Reset();
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    $c.cm.ShowWin(grd_mailList);
    var url = "/DsclSearchAll.do?method=listSendEmail";
    url += "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(txb_LdMktTpCd);
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    dts_emailList.DataID = encodeURI(url);
    dts_emailList.Reset();
};
scwin.initPage = function() {
    scwin.gPvd = $c.stf.getQuery(frame.srcUrl, "frameID");
    scwin.fn_SetHeader();
    scwin.fn_SetData();
    scwin.fn_Search();
};
scwin.fn_Cancel = function() {
    scwin.vCurrPageNo = 0;
    dts_emailList.removeAll();
    scwin.fn_SetHeader();
    scwin.fn_SetData();
    scwin.fn_Search();
};



